args.sql:
-- Check how many artifacts don't have condition assessments
SELECT COUNT(*) FROM "ArtifactsCore" ac 
WHERE NOT EXISTS (SELECT 1 FROM "ConditionAssessments" ca WHERE ca."art_exam" = ac."ARTregID");

-- Check if there are artifacts whose showcase has no environmental readings
WITH latest_ca AS (
  SELECT DISTINCT ON ("art_exam") "art_exam", "case_exam"
  FROM "ConditionAssessments"
  ORDER BY "art_exam", assess_date DESC
)
SELECT COUNT(*) FROM latest_ca lca
WHERE NOT EXISTS (
  SELECT 1 FROM "EnvironmentalReadingsCore" erc WHERE erc.case_link = lca."case_exam"
);

-- Check which artifacts from SensitivityData are also in ConditionAssessments
SELECT sd."ART_link" FROM "SensitivityData" sd
WHERE NOT EXISTS (SELECT 1 FROM "ConditionAssessments" ca WHERE ca."art_exam" = sd."ART_link");

-- Check which artifacts from ArtifactRatings are NOT in SensitivityData
SELECT ar."ART_link" FROM "ArtifactRatings" ar
WHERE NOT EXISTS (SELECT 1 FROM "SensitivityData" sd WHERE sd."ART_link" = ar."ART_link");
